EQUATIONS = {
 'SIS': r'\frac{dI_i}{dt}=\beta_i(t)\left(1-\frac{I_i(t)}{N_i}\right)\sum_j C_{ij}(t)I_j(t)-\gamma_i(t)I_i(t)',
 'C': r'C(t)=\mathrm{Id}+\kappa\tau_0M(t),\qquad S_i=N_i-I_i,\quad x_i=I_i/N_i',
 'RD': r'R_d(t)=\rho\!\left[\mathrm{diag}\!\left(\beta_i(t)(1-x_i(t))\right)C(t)\Gamma(t)^{-1}\right]',
 'GAMMA': r'\Gamma(t)=\mathrm{diag}(\gamma_i(t)),\qquad F(t)=\mathrm{diag}(\beta_i(t)(1-x_i(t)))C(t)',
 'OU': r'dz_i(t)=\vartheta_i(\bar z_i-z_i(t))\,dt+\sigma_i\,dW_i(t),\qquad \beta_i(t)=\bar\beta_i(t)e^{z_i(t)}',
 'OUSTEP': r'z_{k+1}=\bar z+(z_k-\bar z)e^{-\vartheta\Delta t}+\sigma\sqrt{\frac{1-e^{-2\vartheta\Delta t}}{2\vartheta}}\,\xi_k',
 'COUNT': r'm_{ik}^{(r)}=q_i\int_{t_{k-1}}^{t_k}\beta_i^{(r)}(t)(1-x_i^{(r)}(t))\sum_j C_{ij}(t)I_j^{(r)}(t)\,dt',
 'NB': r'Y_{ik}\mid X^{(r)}\sim\mathrm{NB}(m_{ik}^{(r)},k_i),\qquad\mathrm{Var}(Y_{ik}\mid X^{(r)})=m_{ik}^{(r)}+(m_{ik}^{(r)})^2/k_i',
 'BB': r'\pi\sim\mathrm{Beta}(\phi p,\phi(1-p)),\qquad Y\mid\pi\sim\mathrm{Binomial}(n,\pi)',
 'PF': r'\widetilde w_k^{(r)}=w_{k-1}^{(r)}p(Y_k\mid X_k^{(r)}),\qquad w_k^{(r)}=\frac{\widetilde w_k^{(r)}}{\sum_l\widetilde w_k^{(l)}}',
 'ESS': r'\mathrm{ESS}_k=\frac{1}{\sum_r(w_k^{(r)})^2}',
 'QUEUE': r'\frac{d\pi_n}{dt}=a(t)\pi_{n-1}(t)+\mu(t)\min(n+1,m)\pi_{n+1}(t)-[a(t)+\mu(t)\min(n,m)]\pi_n(t)',
 'MU': r'\mu(t)=\mu_0(t)\exp[-\eta_Bx_P(t)]\,o_B(t)',
 'READY': r'R_q^{(s)}=\max\{G_{\mathrm{ship}}^{(s)}+\tau_{\mathrm{transfer},q}^{(s)},D_q^{(s)}\}',
 'TRUCK': r's_q(a)=\max\{R_q,b_q(a)\},\qquad W_q(a)=\max\{R_q-b_q(a),0\}',
 'PROCESS': r'v_L(t)=\frac{1-\eta_Lx_L(t)}{h_0},\qquad Q_L(t)=\int_0^t v_L(u)\,du',
 'GATE': r'Q_L(G_q(a))-Q_L(s_q(a))=1,\qquad A_q(a)=G_q(a)+U_q(a)',
 'EST': r'\widehat\gamma_L=\frac{\int_{t_0}^{t_1}\beta_L(1-y_L)(y_L+c_{LP}y_P)\,dt-[y_L(t_1)-y_L(t_0)]}{\int_{t_0}^{t_1}y_L(t)\,dt}',
 'IDENT': r'x_P(t)=0.5\ \Longrightarrow\ \gamma_P=\beta_P/2;\qquad(a\kappa)(M/a)=\kappa M',
 'RISK': r'\widehat p_q(a)=\sum_r w_{\tau}^{(r)}\frac{1}{S_r}\sum_{s=1}^{S_r}\mathbf{1}\{A_q^{(r,s)}(a)>c_q\}',
 'COST': r'J_q(a)=k_a+c_w\mathbb{E}[W_q(a)]+L_q\widehat p_q(a)',
 'OPT': r'a^*\in\underset{a\in\mathcal A_{\mathrm{feasible}},\ \widehat p_q(a)\leq\varepsilon_q}{\operatorname{arg\,min}}\ J_q(a)',
 'BUDGET': r'\mathrm{Margin}=\mathrm{Subscription}-\mathrm{DataCost}-\mathrm{ComputeCost}-\mathrm{SupportCost}',
}

